/**
 * Checks if a value is a symbol primitive.
 *
 * @public
 * @since v7.0.0
 */
export declare function isSymbol(target: any): target is symbol;
/**
 * Checks if a value is a symbol primitive, Symbol object, or the Symbol constructor.
 *
 * @public
 * @since v7.0.0
 */
export declare function isSymbolOrSymbolClass(target: any): target is symbol;
